Making searchParams optional fixes it for me

```tsx
export default function Journal({
  params,
  searchParams,
}: {
  params: { journal: string };
  searchParams?: { [key: string]: string | string[] };
}) {
  const bgState = useStore((state) => state.setBackgroundState);

  useEffect(() => {
    bgState({ showBg: true });
  }, []);

  return (
    <SMain>
      <SharedJournalContent params={params} searchParams={searchParams!} />
    </SMain>
  );
}
```

> ```ts
> import type { PageComponent } from '../../../../.next/types/app/page';
> ```

The interface for page props is this

```tsx
interface PageProps {
  params: any
  searchParams?: any
}
```
